package cli

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/xml"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

// setup_daemon.go is the install glue behind `setup`: it turns one
// `entire-brain workspace watch <ws>` invocation into a supervised, machine-wide
// background service so the brain stays fresh without anyone remembering to run
// anything.
//
// Everything that decides WHAT gets installed is a pure function of
// (goos, home, spec) — planBrainWatchDaemon and the two renderers below take
// the target OS as an argument rather than reading runtime.GOOS. That is what
// makes the darwin and linux artifacts golden-testable from any machine, and it
// keeps the one genuinely platform-bound part (running launchctl/systemctl)
// behind the injectable CommandRunner.
const (
	// daemonDefaultName is the daemon's identity. It is deliberately a single
	// string: the launchd label and the systemd unit name are both derived from
	// it, so an installation can never end up half-named. Overridable so tests
	// and smoke runs never collide with a real user daemon.
	daemonDefaultName = "entire-brain-watch"

	daemonManagerLaunchd     = "launchd"
	daemonManagerSystemd     = "systemd"
	daemonManagerUnsupported = "unsupported"

	// envDaemonUnitDir redirects the unit FILE (launchd plist / systemd user
	// unit) somewhere other than the real service-manager directory. Tests and
	// smoke runs set it so a run with a REAL $HOME never writes into the
	// developer's ~/Library/LaunchAgents or ~/.config/systemd/user. Redirecting
	// $HOME alone is not enough: a sandboxed process that still sees the real
	// home would write a plist into it.
	//
	// It redirects the FILE AND NOTHING ELSE. `launchctl load -w <path>` and
	// `systemctl --user enable --now` act on the caller's live session whatever
	// directory the unit was read from, so a run that sets only this variable
	// still registers a real, KeepAlive, restart-forever job on the developer's
	// machine. Anything that must not touch the session -- CI, a smoke test,
	// the sandboxed trial harness -- has to set envDaemonNoRegister as well.
	envDaemonUnitDir = "ENTIRE_BRAIN_DAEMON_DIR"

	// envDaemonNoRegister makes the install a DRY RUN against the service
	// manager: the unit file is still written (so its bytes, path and
	// idempotence stay observable) but launchctl/systemctl are never invoked,
	// so nothing is loaded, enabled or started in the caller's session. This is
	// the half envDaemonUnitDir cannot provide, and the reason a CI job that set
	// only the directory still ended up with a live agent.
	envDaemonNoRegister = "ENTIRE_BRAIN_DAEMON_NO_REGISTER"
)

// daemonRegistrationDisabled reports whether this process may talk to the
// service manager at all. Read once, at plan time, so the decision travels with
// the plan and every consumer (install, uninstall, the running-probe) agrees.
func daemonRegistrationDisabled() bool {
	switch strings.ToLower(strings.TrimSpace(os.Getenv(envDaemonNoRegister))) {
	case "", "0", "false", "no":
		return false
	default:
		return true
	}
}

var daemonNamePattern = regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9._-]*$`)

// daemonPathJoin joins path segments for the TARGET operating system, which is
// always a POSIX one here: launchd (darwin) and systemd (linux) are the only
// service managers this file plans for. It is deliberately path.Join — always
// "/" — and never filepath.Join, whose separator is a property of the HOST.
//
// filepath.Join on a Windows host rendered a darwin plan as
// `\Users\demo\Library\LaunchAgents\io.entire...plist`: a path no mac would
// accept, and the reason the darwin/linux golden tests failed on windows CI
// while passing everywhere else. Taking goos as an argument only makes the plan
// portable if every path decision downstream of it is keyed to that argument
// too.
//
// A host-shaped root (a Windows t.TempDir(), or the ENTIRE_BRAIN_DAEMON_DIR
// sandbox) keeps whatever separators it arrived with; only the segments this
// function appends use "/", which every Windows file API accepts, so writing
// the unit still works when a test plans a darwin daemon on a windows box.
func daemonPathJoin(elem ...string) string { return path.Join(elem...) }

// daemonSpec is the full description of the watcher service: which binary to
// run, with which arguments and environment. The environment matters more than
// it looks — a launchd/systemd job inherits almost nothing, so the ENTIRE_PLUGIN_*
// dirs (and PATH, for the `git`/`entire` the refresh shells out to) must be
// carried explicitly or the daemon would silently target a different brain store
// than the CLI that installed it.
type daemonSpec struct {
	Name       string
	Binary     string
	Args       []string
	WorkingDir string
	LogPath    string
	Env        map[string]string
}

// daemonPlan is the resolved, OS-specific install artifact: exactly one file to
// write and the identity to hand the service manager.
type daemonPlan struct {
	OS       string
	Manager  string
	Label    string
	UnitPath string
	Contents string
	Spec     daemonSpec
	// NoRegister carries the envDaemonNoRegister decision. It deliberately does
	// not affect Contents or UnitPath: what would be installed stays exactly
	// what a real run installs, so a sandboxed trial verifies the real artifact
	// and only the service-manager call is withheld.
	NoRegister bool
}

func (p daemonPlan) supported() bool { return p.Manager != daemonManagerUnsupported }

func validateDaemonName(name string) error {
	if !daemonNamePattern.MatchString(name) || strings.ContainsAny(name, `/\`) {
		return fmt.Errorf("daemon name must be a plain identifier (letters, digits, dot, dash, underscore): %q", name)
	}
	return nil
}

// launchdLabel maps the daemon name into Apple's reverse-DNS convention. The
// readable stem alone is NOT injective — stripping the "entire-" prefix maps
// both "entire-watch" and "watch" onto io.entire.watch, so two differently named
// daemons would fight over one launchd job and one plist path. The short digest
// of the FULL name restores injectivity while keeping the label recognisable.
func launchdLabel(name string) string {
	sum := sha256.Sum256([]byte(name))
	return "io.entire." + strings.TrimPrefix(name, "entire-") + "." + hex.EncodeToString(sum[:4])
}

// daemonScopeSuffix distinguishes a daemon installed into an OVERRIDDEN unit
// directory from the real one.
//
// The label used to be derived from the daemon NAME alone, which is constant,
// so every environment on a machine rendered the same label. The plist PATH was
// isolated by ENTIRE_BRAIN_DAEMON_DIR and the LABEL was not, so `launchctl
// bootstrap` of a throwaway unit REPLACED the real registration and repointed
// it at a scratch binary in a directory about to be deleted. That happened
// twice here in one day; the second time it took a bootout/bootstrap to undo.
//
// Only an overridden directory gets a suffix. The default must keep rendering
// the label it always has, or every existing install is orphaned on upgrade --
// a migration this cannot justify when the whole point is not breaking things.
func daemonScopeSuffix(unitDir string) string {
	unitDir = strings.TrimSpace(unitDir)
	if unitDir == "" {
		return ""
	}
	sum := sha256.Sum256([]byte(unitDir))
	return "." + hex.EncodeToString(sum[:4])
}

// systemdUnitName is the daemon name with the unit suffix; systemd unit names
// are already plain identifiers, so no transformation is needed.
func systemdUnitName(name string) string { return name + ".service" }

// planBrainWatchDaemon resolves the spec against a target OS and home directory.
// goos/home/configHome/unitDir are parameters, not ambient state, so both
// platforms' artifacts are testable from one machine. A non-empty unitDir (the
// ENTIRE_BRAIN_DAEMON_DIR knob) replaces the service manager's directory
// entirely, which is what keeps a sandboxed run out of a real user's LaunchAgents.
func planBrainWatchDaemon(goos, home, configHome, unitDir string, spec daemonSpec) (daemonPlan, error) {
	if strings.TrimSpace(spec.Name) == "" {
		spec.Name = daemonDefaultName
	}
	if err := validateDaemonName(spec.Name); err != nil {
		return daemonPlan{}, err
	}
	if strings.TrimSpace(spec.Binary) == "" {
		return daemonPlan{}, fmt.Errorf("daemon binary path is required")
	}
	// A newline in any rendered value would close the line and let the rest be
	// read as further unit directives. No escaping expresses it; refuse instead.
	values := append([]string{spec.Binary, spec.WorkingDir, spec.LogPath}, spec.Args...)
	for key, value := range spec.Env {
		values = append(values, key, value)
	}
	for _, value := range values {
		if !unitValueSafe(value) {
			return daemonPlan{}, fmt.Errorf("daemon service values must not contain newlines: %q", value)
		}
	}
	unitDir = strings.TrimSpace(unitDir)
	plan := daemonPlan{OS: goos, Spec: spec}
	switch goos {
	case "darwin":
		if home == "" && unitDir == "" {
			return daemonPlan{}, fmt.Errorf("cannot resolve home directory for the launchd agent")
		}
		plan.Manager = daemonManagerLaunchd
		plan.Label = launchdLabel(spec.Name) + daemonScopeSuffix(unitDir)
		root := unitDir
		if root == "" {
			root = daemonPathJoin(home, "Library", "LaunchAgents")
		}
		plan.UnitPath = daemonPathJoin(root, plan.Label+".plist")
		plan.Contents = renderLaunchdPlist(plan.Label, spec)
	case "linux":
		root := unitDir
		if root == "" {
			root = configHome
			if root == "" {
				if home == "" {
					return daemonPlan{}, fmt.Errorf("cannot resolve config directory for the systemd user unit")
				}
				root = daemonPathJoin(home, ".config")
			}
			root = daemonPathJoin(root, "systemd", "user")
		}
		plan.Manager = daemonManagerSystemd
		// Same hazard as launchd: the unit NAME is constant, so a throwaway
		// install into an overridden directory would otherwise collide with
		// the real unit. Fixing one platform and not the other is how the two
		// halves drift apart.
		plan.Label = systemdUnitName(spec.Name + strings.ReplaceAll(daemonScopeSuffix(unitDir), ".", "-"))
		plan.UnitPath = daemonPathJoin(root, plan.Label)
		plan.Contents = renderSystemdUnit(spec)
	default:
		plan.Manager = daemonManagerUnsupported
		plan.Label = spec.Name
	}
	return plan, nil
}

// sortedEnvKeys keeps rendered artifacts byte-stable across runs (Go map order
// is randomized), which is what lets idempotence be decided by comparing the
// file on disk against the freshly rendered plan.
func sortedEnvKeys(env map[string]string) []string {
	keys := make([]string, 0, len(env))
	for key := range env {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

func xmlEscape(value string) string {
	var buf bytes.Buffer
	_ = xml.EscapeText(&buf, []byte(value))
	return buf.String()
}

func renderLaunchdPlist(label string, spec daemonSpec) string {
	var b strings.Builder
	b.WriteString(`<?xml version="1.0" encoding="UTF-8"?>` + "\n")
	b.WriteString(`<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">` + "\n")
	b.WriteString(`<plist version="1.0">` + "\n")
	b.WriteString("<dict>\n")
	fmt.Fprintf(&b, "  <key>Label</key>\n  <string>%s</string>\n", xmlEscape(label))
	b.WriteString("  <key>ProgramArguments</key>\n  <array>\n")
	for _, arg := range append([]string{spec.Binary}, spec.Args...) {
		fmt.Fprintf(&b, "    <string>%s</string>\n", xmlEscape(arg))
	}
	b.WriteString("  </array>\n")
	if len(spec.Env) > 0 {
		b.WriteString("  <key>EnvironmentVariables</key>\n  <dict>\n")
		for _, key := range sortedEnvKeys(spec.Env) {
			fmt.Fprintf(&b, "    <key>%s</key>\n    <string>%s</string>\n", xmlEscape(key), xmlEscape(spec.Env[key]))
		}
		b.WriteString("  </dict>\n")
	}
	if spec.WorkingDir != "" {
		fmt.Fprintf(&b, "  <key>WorkingDirectory</key>\n  <string>%s</string>\n", xmlEscape(spec.WorkingDir))
	}
	if spec.LogPath != "" {
		fmt.Fprintf(&b, "  <key>StandardOutPath</key>\n  <string>%s</string>\n", xmlEscape(spec.LogPath))
		fmt.Fprintf(&b, "  <key>StandardErrorPath</key>\n  <string>%s</string>\n", xmlEscape(spec.LogPath))
	}
	b.WriteString("  <key>RunAtLoad</key>\n  <true/>\n")
	b.WriteString("  <key>KeepAlive</key>\n  <true/>\n")
	// A crash-looping watcher must not spin: 60s between relaunches is far
	// below the 5m tick, so a healthy daemon never notices the throttle.
	b.WriteString("  <key>ThrottleInterval</key>\n  <integer>60</integer>\n")
	b.WriteString("  <key>ProcessType</key>\n  <string>Background</string>\n")
	b.WriteString("  <key>LowPriorityIO</key>\n  <true/>\n")
	b.WriteString("</dict>\n</plist>\n")
	return b.String()
}

// systemdQuote renders a value for systemd's quoted argument syntax. Use it
// ONLY for settings systemd unquotes — the ones parsed with extract_first_word
// (EXTRACT_UNQUOTE): ExecStart= and Environment=.
func systemdQuote(value string) string {
	replacer := strings.NewReplacer(`\`, `\\`, `"`, `\"`)
	return `"` + systemdEscapeSpecifiers(replacer.Replace(value)) + `"`
}

// systemdSingleValue renders a value for a setting that takes ONE value and is
// NOT unquoted by systemd: WorkingDirectory=, StandardOutput=, StandardError=.
//
// Those are parsed by config_parse_working_directory / config_parse_exec_output,
// which run unit_path_printf on the raw right-hand side and never call
// extract_first_word — so a quoted path arrives with its quote characters still
// in it and is then rejected by path_simplify_and_warn's absolute-path check.
// Wrapping these in quotes does not harden them, it breaks them. Spaces need no
// treatment at all here: the whole rest of the line is the value.
//
// What DOES need handling is the one transformation systemd applies to them,
// specifier expansion: a literal % must be written %% or it is silently read as
// a specifier (e.g. %h expands to the home directory). Newlines cannot be
// represented in a unit value in any form and are rejected by the caller.
func systemdSingleValue(value string) string {
	return systemdEscapeSpecifiers(value)
}

func systemdEscapeSpecifiers(value string) string {
	return strings.ReplaceAll(value, "%", "%%")
}

// unitValueSafe rejects the values no unit-file escaping can express. A newline
// would end the line and turn the remainder into a forged directive.
func unitValueSafe(value string) bool {
	return !strings.ContainsAny(value, "\n\r")
}

func renderSystemdUnit(spec daemonSpec) string {
	var b strings.Builder
	b.WriteString("[Unit]\n")
	b.WriteString("Description=Entire brain watcher (deterministic refresh is free; agent steps are gated)\n")
	b.WriteString("Documentation=https://github.com/entireio/entire-brain\n")
	b.WriteString("After=default.target\n\n")
	b.WriteString("[Service]\n")
	b.WriteString("Type=simple\n")
	exec := make([]string, 0, len(spec.Args)+1)
	for _, arg := range append([]string{spec.Binary}, spec.Args...) {
		exec = append(exec, systemdQuote(arg))
	}
	fmt.Fprintf(&b, "ExecStart=%s\n", strings.Join(exec, " "))
	if spec.WorkingDir != "" {
		fmt.Fprintf(&b, "WorkingDirectory=%s\n", systemdSingleValue(spec.WorkingDir))
	}
	for _, key := range sortedEnvKeys(spec.Env) {
		fmt.Fprintf(&b, "Environment=%s\n", systemdQuote(key+"="+spec.Env[key]))
	}
	if spec.LogPath != "" {
		fmt.Fprintf(&b, "StandardOutput=append:%s\n", systemdSingleValue(spec.LogPath))
		fmt.Fprintf(&b, "StandardError=append:%s\n", systemdSingleValue(spec.LogPath))
	}
	b.WriteString("Restart=always\n")
	b.WriteString("RestartSec=60\n")
	b.WriteString("Nice=10\n\n")
	b.WriteString("[Install]\n")
	b.WriteString("WantedBy=default.target\n")
	return b.String()
}

// daemonPathPlaceholder stands in for the inherited search path while two
// rendered units are compared. It is never written to disk.
const daemonPathPlaceholder = "\x00entire-brain-daemon-path\x00"

// daemonUnitMaterial reduces a rendered unit to the part that decides what the
// daemon DOES, so `Current` answers "would this build install a different
// service" instead of "was this shell's environment byte-identical to the one
// that installed it".
//
// The only ambient value in the unit is PATH. daemonEnv copies it from the
// installing process because a launchd/systemd job inherits almost nothing and
// the deterministic refresh shells out to `git` and `entire` — but PATH is the
// most volatile variable on a developer machine. Installing a tool, opening a
// different terminal, a shell rc that prepends a directory twice: any of those
// made the on-disk unit differ from the freshly rendered one by a single line.
//
// Byte equality therefore reported drift on a perfectly good service, and
// `setup` "repairs" drift by unloading and reloading it — tearing down the ONE
// machine-wide watcher, mid-refresh, on a re-run that changed nothing. `status`
// meanwhile told the user their running watcher was stale and to re-run the
// command that would do it again. This is the same failure the log path caused
// before it was made machine-level (see brainWatchDaemonPlan); PATH is the
// remaining instance of it, and the more volatile one.
//
// Masking is deliberately narrow: only the PATH VALUE is neutralized. A unit
// that gains or loses PATH entirely, or whose binary, arguments, working
// directory, log path or ENTIRE_PLUGIN_* dirs changed, still reads as drift and
// is still repaired — and a real reinstall always writes the current PATH.
func daemonUnitMaterial(manager, contents string) string {
	lines := strings.Split(contents, "\n")
	switch manager {
	case daemonManagerLaunchd:
		for i, line := range lines {
			if strings.TrimSpace(line) != "<key>PATH</key>" || i+1 >= len(lines) {
				continue
			}
			next := strings.TrimSpace(lines[i+1])
			if strings.HasPrefix(next, "<string>") && strings.HasSuffix(next, "</string>") {
				lines[i+1] = daemonPathPlaceholder
			}
		}
	case daemonManagerSystemd:
		for i, line := range lines {
			if strings.HasPrefix(strings.TrimSpace(line), `Environment="PATH=`) {
				lines[i] = daemonPathPlaceholder
			}
		}
	default:
		return contents
	}
	return strings.Join(lines, "\n")
}

// setupDaemonLockName serializes the daemon REGISTRATION sequence across
// processes. It lives beside the machine-level watch plan, in the plugin state
// dir, for the same reason the plan does: exactly one service exists per
// machine, so the thing that guards it must be machine-level too.
const setupDaemonLockName = "daemon-install.lock"

// withDaemonRegistrationLock runs fn holding the machine-level daemon lock.
//
// `setup` decides what to do about the daemon with inspect() and then acts with
// install()/uninstall(), and install() on darwin is not one call but two
// (`launchctl unload` then `launchctl load -w`) with the service DOWN in
// between. None of that was serialized, while the watch plan written moments
// earlier — the far less dangerous file — already was. Two repos onboarding at
// once is the ordinary case this whole file was rewritten for, and interleaving
// two unload/load pairs against one label means one run's `load` can land
// between the other's `unload` and `load`: the second then fails with "service
// already loaded" and `setup` reports "daemon install failed" for a watcher
// that is in fact running. Every process now observes the service, changes it
// and re-observes it as one atomic step.
//
// It degrades rather than fails: a state dir that cannot be resolved or locked
// runs fn unlocked, because a machine that cannot take the lock must still be
// able to install its watcher.
func withDaemonRegistrationLock(env EntireEnv, fn func() error) error {
	planPath, err := setupWatchPlanPath(env)
	if err != nil {
		return fn()
	}
	stateDir := filepath.Dir(planPath)
	if err := rejectExistingSymlinkPathComponents(stateDir, brainLockDirName); err != nil {
		return fn()
	}
	lock, err := acquireFileLock(filepath.Join(stateDir, brainLockDirName, setupDaemonLockName), "daemon_install_locked", brainWriteLockTimeout)
	if err != nil {
		return fn()
	}
	defer func() { _ = lock.Close() }()
	return fn()
}

// daemonState is what `setup` and `status` report about the installed watcher.
type daemonState struct {
	Manager   string `json:"manager"`
	Label     string `json:"label,omitempty"`
	UnitPath  string `json:"unit_path,omitempty"`
	Installed bool   `json:"installed"`
	// Current is true when the file on disk matches what this build would
	// write. A stale unit is "installed" but must be rewritten — that is the
	// difference between idempotent re-run and silent drift.
	Current bool   `json:"current"`
	Running bool   `json:"running"`
	Detail  string `json:"detail,omitempty"`
}

// inspectDaemon reports the installed/current/running triple without changing
// anything. Detection is deliberately cheap: one file read plus one service
// manager query.
func inspectDaemon(ctx context.Context, runner CommandRunner, plan daemonPlan) daemonState {
	state := daemonState{Manager: plan.Manager, Label: plan.Label, UnitPath: plan.UnitPath}
	if !plan.supported() {
		// Same wording setup's skip line uses, so `status` and `setup` describe
		// one platform fact the same way instead of two apparent conditions.
		state.Detail = "not supported on " + plan.OS + " yet (no launchd or systemd)"
		return state
	}
	data, err := os.ReadFile(plan.UnitPath)
	switch {
	case err == nil:
		state.Installed = true
		state.Current = daemonUnitMaterial(plan.Manager, string(data)) == daemonUnitMaterial(plan.Manager, plan.Contents)
	case os.IsNotExist(err):
		// Nothing installed under this label, so nothing can be running under
		// it either. Skipping the probe keeps `status` free of a subprocess on
		// the overwhelmingly common not-set-up path.
		return state
	default:
		state.Detail = "read unit: " + err.Error()
		return state
	}
	state.Running, state.Detail = daemonRunning(ctx, runner, plan)
	return state
}

func daemonRunning(ctx context.Context, runner CommandRunner, plan daemonPlan) (bool, string) {
	if plan.NoRegister {
		// Never probe the live session in a no-register run: `launchctl list`
		// against a real label would report a job this process did not install
		// and must not claim.
		return false, "not registered (" + envDaemonNoRegister + ")"
	}
	if runner == nil {
		return false, "no command runner"
	}
	switch plan.Manager {
	case daemonManagerLaunchd:
		if _, _, err := runner.Run(ctx, "", "launchctl", "list", plan.Label); err != nil {
			return false, ""
		}
		return true, ""
	case daemonManagerSystemd:
		stdout, _, err := runner.Run(ctx, "", "systemctl", "--user", "is-active", plan.Label)
		// systemctl exits nonzero for every inactive state, so the stdout word
		// is the signal, not the exit code.
		if strings.TrimSpace(string(stdout)) == "active" {
			return true, ""
		}
		if err != nil {
			return false, ""
		}
		return false, ""
	}
	return false, ""
}

// refreshDaemonUnitBytes rewrites the unit file when it differs from what this
// build would install, WITHOUT going near the service manager.
//
// It is the other half of daemonUnitMaterial. Masking PATH out of the
// "is it current" decision correctly stops `setup` from tearing the live
// watcher down over a shell variable — but on its own it would also freeze the
// daemon's PATH at whatever the very first install happened to inherit, with
// nothing ever refreshing it. Writing the file here and reloading nothing gets
// both: the running service is left strictly alone, and it picks up the current
// PATH at its next natural restart (login, crash, reboot).
//
// A failure is deliberately not an error to the caller: the watcher is running
// and correct, and refusing a re-run of `setup` over a cosmetic rewrite would
// be worse than skipping it.
func refreshDaemonUnitBytes(plan daemonPlan) error {
	if !plan.supported() {
		return nil
	}
	data, err := os.ReadFile(plan.UnitPath)
	if err != nil || string(data) == plan.Contents {
		return err
	}
	return writeFileAtomic(plan.UnitPath, []byte(plan.Contents), 0o600)
}

// installDaemon writes the unit and (re)loads it. It is idempotent by
// construction: the file write is unconditional-but-identical when nothing
// changed, and the unload-then-load pair leaves exactly one job registered no
// matter how many times setup runs.
func installDaemon(ctx context.Context, runner CommandRunner, plan daemonPlan) error {
	if !plan.supported() {
		return fmt.Errorf("no supported service manager for %s", plan.OS)
	}
	if err := os.MkdirAll(filepath.Dir(plan.UnitPath), 0o755); err != nil {
		return fmt.Errorf("create service directory: %w", err)
	}
	if plan.Spec.LogPath != "" {
		if err := os.MkdirAll(filepath.Dir(plan.Spec.LogPath), 0o700); err != nil {
			return fmt.Errorf("create log directory: %w", err)
		}
	}
	if err := writeFileAtomic(plan.UnitPath, []byte(plan.Contents), 0o600); err != nil {
		return fmt.Errorf("write %s: %w", plan.UnitPath, err)
	}
	if runner == nil || plan.NoRegister {
		// No-register: the unit file is on disk and byte-identical to what a
		// real install would write, and the caller's launchd/systemd session is
		// untouched.
		return nil
	}
	switch plan.Manager {
	case daemonManagerLaunchd:
		// Unload first so a re-run replaces a stale job instead of failing with
		// "service already loaded" — this is the idempotence hinge on darwin.
		_, _, _ = runner.Run(ctx, "", "launchctl", "unload", plan.UnitPath)
		if _, stderr, err := runner.Run(ctx, "", "launchctl", "load", "-w", plan.UnitPath); err != nil {
			return fmt.Errorf("launchctl load: %w: %s", err, strings.TrimSpace(string(stderr)))
		}
	case daemonManagerSystemd:
		if _, stderr, err := runner.Run(ctx, "", "systemctl", "--user", "daemon-reload"); err != nil {
			return fmt.Errorf("systemctl daemon-reload: %w: %s", err, strings.TrimSpace(string(stderr)))
		}
		if _, stderr, err := runner.Run(ctx, "", "systemctl", "--user", "enable", "--now", plan.Label); err != nil {
			return fmt.Errorf("systemctl enable --now: %w: %s", err, strings.TrimSpace(string(stderr)))
		}
	}
	return nil
}

// uninstallDaemon stops the service and removes the unit. Missing state is not
// an error: uninstalling twice must succeed.
func uninstallDaemon(ctx context.Context, runner CommandRunner, plan daemonPlan) error {
	if !plan.supported() {
		return nil
	}
	if _, err := os.Stat(plan.UnitPath); os.IsNotExist(err) {
		return nil
	} else if err != nil {
		return err
	}
	if runner != nil && !plan.NoRegister {
		switch plan.Manager {
		case daemonManagerLaunchd:
			if _, stderr, err := runner.Run(ctx, "", "launchctl", "unload", "-w", plan.UnitPath); err != nil {
				return fmt.Errorf("launchctl unload: %w: %s", err, strings.TrimSpace(string(stderr)))
			}
		case daemonManagerSystemd:
			if _, stderr, err := runner.Run(ctx, "", "systemctl", "--user", "disable", "--now", plan.Label); err != nil {
				return fmt.Errorf("systemctl disable --now: %w: %s", err, strings.TrimSpace(string(stderr)))
			}
		}
	}
	if err := os.Remove(plan.UnitPath); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("remove %s: %w", plan.UnitPath, err)
	}
	if runner != nil && !plan.NoRegister && plan.Manager == daemonManagerSystemd {
		_, _, _ = runner.Run(ctx, "", "systemctl", "--user", "daemon-reload")
	}
	return nil
}

const (
	// daemonLogMaxBytes caps the installed watcher's log before it is rotated.
	// The watcher is a KeepAlive service meant to run for months and it prints
	// several lines PER TICK PER REPO — plus, on a brain whose manifest cannot
	// be parsed, three error lines every tick forever. Nothing rotated that
	// file: not launchd (StandardOutPath is a plain append), not systemd
	// (append: likewise), and not this program, which caps the memory worker's
	// log at 1 MiB and the facts vitality log at 1 MiB but left the one log
	// that grows fastest and lives longest unbounded.
	//
	// 4 MiB plus one archive keeps roughly a week of healthy five-minute ticks
	// readable while bounding the whole thing at 8 MiB.
	daemonLogMaxBytes = 4 << 20
	// daemonLogArchiveSuffix names the single retained previous generation.
	daemonLogArchiveSuffix = ".1"
)

// daemonLogPath resolves the file the installed unit points stdout and stderr
// at. It is derived from the plugin state dir exactly as brainWatchDaemonPlan
// derives it, so the running watcher can find its own log without the unit
// having to tell it — which means no unit bytes change and no installed daemon
// is restarted to gain rotation.
func daemonLogPath(env EntireEnv) (string, error) {
	dirs, err := resolvePluginDirs(env)
	if err != nil {
		return "", err
	}
	return filepath.Join(dirs.State, "logs", setupDaemonLogFile), nil
}

// rotateDaemonLogIfLarge copies the log aside and truncates it IN PLACE.
//
// Truncation rather than rename is the whole point: launchd and systemd opened
// this file with O_APPEND before the process started and hold that descriptor
// for the life of the job. Renaming it would leave the service writing to the
// renamed inode forever and the fresh file permanently empty, so the log would
// appear to stop. An O_APPEND write always seeks to the end first, so after
// truncation the very next line lands at offset 0.
//
// Anything that is not a plain regular file is left alone, so a watcher run in
// a terminal, or one whose log path has been replaced with a symlink, is never
// touched.
func rotateDaemonLogIfLarge(path string, maxBytes int64) error {
	if maxBytes <= 0 {
		return nil
	}
	info, err := os.Lstat(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	if !info.Mode().IsRegular() || info.Size() <= maxBytes {
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if err := writeFileAtomic(path+daemonLogArchiveSuffix, data, 0o600); err != nil {
		return err
	}
	return os.Truncate(path, 0)
}

// daemonLogMaintainer returns the per-pass upkeep for a watcher that IS the
// installed service, and nil for every other caller.
//
// The test is identity, not configuration: the returned closure exists only
// when this process's stdout is the very file the unit names. A `workspace
// watch` run by hand in a terminal, a test with a buffer, or a second watcher
// redirected somewhere else therefore cannot truncate the daemon's log — only
// the process actually writing to it can.
func daemonLogMaintainer(env EntireEnv) func() {
	path, err := daemonLogPath(env)
	if err != nil {
		return nil
	}
	if !stdoutIsFile(path) {
		return nil
	}
	return func() { _ = rotateDaemonLogIfLarge(path, daemonLogMaxBytes) }
}

func stdoutIsFile(path string) bool {
	target, err := os.Stat(path)
	if err != nil {
		return false
	}
	mine, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return os.SameFile(mine, target)
}

package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"os/signal"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"time"

	"github.com/spf13/cobra"
)

// watch keeps the brain fresh automatically. Token-frugality is structural, not a quota:
// the deterministic refresh (sessions + semantic index + durable history reconciliation, seed agent
// ALWAYS "none") spends ZERO agent tokens and runs whenever the checkpoint/HEAD fingerprint changes.
// The ONLY token-spending
// work — distill and/or agent seed synthesis (--seed-agent) — is OFF by default and, when enabled, runs
// at most once per --distill-every, on the cheap --model/--effort, capped by --budget, and a persisted
// cursor means a restart never re-spends within the interval. Both token steps share the one gate, so
// --seed-agent is bounded exactly like --distill (it is NOT per-change spend).
type watchCommandOptions struct {
	interval time.Duration
	once     bool
	// consolidateEvery throttles the FULL deterministic refresh (consolidation:
	// sessions + semantic + history + clearing short-term memory). The
	// fingerprint includes checkpoint refs, so during active agent work every
	// turn would otherwise trigger the heavy path each tick; the per-tick
	// short-term delta carries freshness in between. 0 = consolidate on every
	// change (the pre-short-term behavior). A full short-term buffer always
	// forces consolidation regardless of the interval.
	consolidateEvery time.Duration
	distill          bool
	distillEvery     time.Duration
	distillAgent     string
	distillJobs      int
	// distillMaxSessions caps how many NOT-YET-DISTILLED sessions one gated
	// pass processes (0 = no cap). --distill-every and the persisted cursor
	// bound how OFTEN the daemon spends; this is the only thing that bounds how
	// MUCH one spend costs. Without it a supervised watcher's first gated tick
	// distills the entire remaining corpus of every repo in the workspace —
	// exactly the spend `setup` told the user it had capped at 25.
	distillMaxSessions int
	seedAgent          string
	model              string
	effort             string
	// budget caps gated agent runs for the life of THIS PROCESS (distill + seed;
	// each spends tokens); 0 = unlimited. It is not window-scoped and never
	// resets while the process lives, which makes it the wrong guard for a
	// supervised daemon — see brainWatchDaemonArgs, which deliberately omits it.
	budget int
}

// watchCursor persists across restarts so the daemon never re-refreshes unchanged state and never
// re-runs the gated agent work within --distill-every after a restart.
type watchCursor struct {
	PendingSeed      bool      `json:"pending_seed,omitempty"`
	PendingDistill   bool      `json:"pending_distill,omitempty"`
	LastFingerprint  string    `json:"last_fingerprint"`
	LastRefreshAt    time.Time `json:"last_refresh_at,omitempty"`
	LastAgentSpendAt time.Time `json:"last_agent_spend_at,omitempty"`
	// ConsolidationRepairs counts CONSECUTIVE full refreshes that ran early
	// because the short-term delta failed. It is the backoff state for
	// watchRepairWait: a single failure repairs promptly, a persistent one
	// settles back to the normal consolidation cadence instead of firing the
	// heavy refresh every tick. Reset to 0 by the first healthy delta.
	ConsolidationRepairs int       `json:"consolidation_repairs,omitempty"`
	LastFactsSyncAt      time.Time `json:"last_facts_sync_at,omitempty"`
}

// watchRepairBackoffMax caps ConsolidationRepairs so the persisted counter stays
// bounded and the doubling in watchRepairWait can never overflow.
const watchRepairBackoffMax = 16

const watchCursorLockName = "watch.lock"

// watchSteps are the side-effecting operations of one tick. Injected so the loop's gating logic
// (change detection, agent interval/budget, cursor persistence) is unit-testable without running a real
// refresh/seed/distill. refresh is ALWAYS the free (seed-agent none) deterministic refresh; seed and
// distill are the gated, token-spending steps.
type watchSteps struct {
	now         func() time.Time
	fingerprint func(context.Context) string
	// delta is the cheap short-term memory update (incremental export + overlay
	// index of changed transcripts). It runs EVERY tick, before the change
	// gate, so an in-flight session's turns are recallable near-real-time; the
	// full refresh below is consolidation and is throttled by
	// --consolidate-every unless the delta reports the buffer full.
	delta func(context.Context) (shortTermStats, error)
	// reconcile durably queues long-term conversation work independently of
	// the git/checkpoint fingerprint. Exported transcripts can change while
	// that fingerprint stays stable (for example, a late host export).
	reconcile func(context.Context) error
	refresh   func(context.Context) error
	seed      func(context.Context) error
	distill   func(context.Context) error
	// factsSync publishes-and-pulls hosted facts (hostedFactsSyncAndPull) for
	// the current + default branch. Nil when the surface has no hosted step;
	// non-fatal and cursor-throttled (hostedSyncMinInterval).
	factsSync func(context.Context) (bool, error)
	paused    func() bool
}

// hostedSyncMinInterval throttles the hosted fact sync step across ticks: the
// tick interval is minutes, a team's fact churn is hours.
const hostedSyncMinInterval = 15 * time.Minute

// defaultWatchOptions are the shared defaults for `watch` and `workspace watch`.
func defaultWatchOptions() watchCommandOptions {
	return watchCommandOptions{
		interval:         5 * time.Minute,
		consolidateEvery: 30 * time.Minute,
		distillEvery:     24 * time.Hour,
		// "auto", not "codex". A hardcoded vendor here was a THIRD codex default
		// that never reached defaultRefreshAgent at all, so reordering that
		// function alone would have left the watcher — the one unattended path
		// that spends tokens on its own — routing repository content to codex
		// forever. runDistill resolves "auto" on this path (distill_cmd.go), and
		// `setup` still overrides it per workspace through the watch plan.
		distillAgent: "auto",
		distillJobs:  1,
		seedAgent:    "none",
	}
}

// bindWatchFlags registers the watch flags on a command, shared so `watch` and `workspace watch` expose
// the identical token-frugality controls.
func bindWatchFlags(cmd *cobra.Command, w *watchCommandOptions) {
	cmd.Flags().DurationVar(&w.interval, "interval", w.interval, "Poll interval between ticks")
	cmd.Flags().DurationVar(&w.consolidateEvery, "consolidate-every", w.consolidateEvery, "Minimum interval between full consolidations (heavy refresh); the per-tick short-term delta covers freshness in between. 0 = consolidate on every change; a full short-term buffer always consolidates")
	cmd.Flags().BoolVar(&w.once, "once", false, "Run a single pass and exit (no daemon loop)")
	cmd.Flags().BoolVar(&w.distill, "distill", false, "Run distill (SPENDS TOKENS) when new sessions land — gated by --distill-every + --budget")
	cmd.Flags().DurationVar(&w.distillEvery, "distill-every", w.distillEvery, "Minimum interval between gated agent runs (distill and/or seed synthesis)")
	cmd.Flags().StringVar(&w.distillAgent, "agent", w.distillAgent, "Agent for the distill step (used only with --distill)")
	cmd.Flags().IntVar(&w.distillJobs, "jobs", w.distillJobs, "Parallel distill extraction jobs when --distill is enabled; reconciliation and writes remain deterministic")
	cmd.Flags().IntVar(&w.distillMaxSessions, "max-sessions", w.distillMaxSessions, "Cap how many not-yet-distilled sessions ONE gated distill pass processes (0 = no cap). --distill-every bounds how often the daemon spends; this bounds how much each spend costs")
	cmd.Flags().StringVar(&w.seedAgent, "seed-agent", w.seedAgent, "Agent for gated seed synthesis (SPENDS TOKENS); none = deterministic seed only. Bounded by --distill-every + --budget, NOT per-change")
	cmd.Flags().StringVar(&w.model, "model", "", "Fast/cheap model for the gated agent steps (distill/seed)")
	cmd.Flags().StringVar(&w.effort, "effort", "", "Reasoning effort for the gated agent steps (codex --config model_reasoning_effort=, claude --effort)")
	cmd.Flags().IntVar(&w.budget, "budget", 0, "Cap on gated agent runs for the LIFE OF THIS PROCESS (distill + seed); 0 = unlimited. It never resets, so on a long-lived daemon --budget 1 means one run EVER, not one per window — the durable per-window guard is --distill-every + the persisted cursor. Use it only for a bounded foreground run.")
}

func newWatchCommand(opts Options) *cobra.Command {
	w := defaultWatchOptions()
	cmd := &cobra.Command{
		Use:   "watch [path]",
		Short: "Keep the brain up to date automatically",
		Long:  "Keep the brain fresh automatically (deterministic refresh is free; agent steps are gated)",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			target := "."
			if len(args) == 1 {
				target = args[0]
			}
			return runWatch(cmd.Context(), cmd, opts, w, target)
		},
	}
	bindWatchFlags(cmd, &w)
	return cmd
}

func runWatch(ctx context.Context, cmd *cobra.Command, opts Options, w watchCommandOptions, target string) error {
	if w.interval <= 0 {
		w.interval = 5 * time.Minute
	}
	if w.distillJobs <= 0 {
		return fmt.Errorf("--jobs must be greater than 0")
	}
	now := opts.Now
	if now == nil {
		now = time.Now
	}
	repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
	if err != nil {
		return err
	}
	if !local {
		return fmt.Errorf("watch requires a local repository path: %s", target)
	}
	storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
	if err != nil {
		return err
	}
	cursorPath := filepath.Join(filepath.Dir(storage.HeadPath), "watch.json")
	steps := watchStepsForRepo(cmd, opts, w, repoDir, now)
	// Wire SIGINT/SIGTERM so a long-running daemon stops cleanly between ticks instead of being killed
	// mid-refresh; this is what makes the loop's ctx-cancel paths live (the root command runs with a
	// Background context otherwise).
	ctx, stop := watchSignalContext(ctx)
	defer stop()
	fmt.Fprintf(cmd.OutOrStdout(), "[watch] %s — interval %s, distill=%v (every %s, agent=%s, jobs=%d, model=%q, max-sessions=%s, run-budget=%s)\n",
		storage.Key, w.interval, w.distill, w.distillEvery, w.distillAgent, w.distillJobs, w.model,
		watchCapLabel(w.distillMaxSessions), watchCapLabel(w.budget))
	return watchLoop(ctx, cmd.OutOrStdout(), w, cursorPath, steps)
}

// watchCapLabel renders a cap where a non-positive value means "no cap".
//
// The banner printed a bare "budget=0", and 0 is the value a setup-installed
// watcher ALWAYS has: setup deliberately never passes --budget, because that
// counter is process-lifetime and never resets (see brainWatchDaemonArgs). So
// the one number the daemon's log offered about spend was both meaningless and
// easy to read as "zero allowed", while the cap that actually binds it --
// --max-sessions, carried per workspace in the machine watch plan -- was not
// printed at all.
func watchCapLabel(value int) string {
	if value <= 0 {
		return "uncapped"
	}
	return strconv.Itoa(value)
}

// watchSignalContext returns a context cancelled on SIGINT/SIGTERM so `watch` and `workspace watch`
// shut down cleanly between ticks (finish the current tick, then return) rather than dying abruptly.
func watchSignalContext(ctx context.Context) (context.Context, context.CancelFunc) {
	return signal.NotifyContext(ctx, os.Interrupt, syscall.SIGTERM)
}

func watchLoop(ctx context.Context, out io.Writer, w watchCommandOptions, cursorPath string, steps watchSteps) error {
	agentCalls := 0
	for {
		if ctx.Err() != nil {
			fmt.Fprintln(out, "[watch] stopping")
			return nil
		}
		watchTick(ctx, out, w, cursorPath, steps, &agentCalls)
		if w.once {
			return nil
		}
		select {
		case <-ctx.Done():
			fmt.Fprintln(out, "[watch] stopping")
			return nil
		case <-time.After(w.interval):
		}
	}
}

// watchTick runs one pass: cheap change detection, then (only on change) the free deterministic refresh,
// then the GATED token-spending work (seed synthesis and/or distill). agentCalls is shared across
// ticks/members so --budget caps total token spend across the whole run.
func watchTick(ctx context.Context, out io.Writer, w watchCommandOptions, cursorPath string, steps watchSteps, agentCalls *int) {
	if steps.paused != nil && steps.paused() {
		fmt.Fprintln(out, "[watch] paused — `entire-brain start` resumes")
		return
	}
	// Short-term memory first, every tick: cheap (change detection + only
	// changed transcripts), and it must never block or fail the tick; a delta
	// failure just means the long-term path repairs freshness later.
	bufferFull := false
	// No delta step configured means there is no short-term path that could
	// have failed, so the throttle applies at its normal cadence rather than
	// treating every tick as a repair.
	deltaHealthy := true
	deltaNeedsReconcile := false
	if steps.delta != nil {
		stats, err := steps.delta(ctx)
		if err != nil {
			deltaHealthy = false
			deltaNeedsReconcile = true
			fmt.Fprintf(out, "[watch] short-term memory update failed (continuing): %v\n", err)
		} else {
			// A delta that failed to scan any transcript did NOT fully carry
			// the new work, so it must not defer consolidation.
			deltaHealthy = stats.Failed == 0
			bufferFull = stats.Truncated
			deltaNeedsReconcile = stats.Files > 0 || stats.Failed > 0 || stats.Truncated
			fmt.Fprintf(out, "[watch] short-term memory updated (%d records from %d changed transcripts)\n", stats.Records, stats.Files)
			if stats.Failed > 0 {
				fmt.Fprintf(out, "[watch] short-term memory incomplete: %d transcripts failed to scan; consolidation will repair\n", stats.Failed)
			}
		}
	}
	// Delta state is itself a source-change signal. Do this before the git
	// fingerprint gate so a changed/failed/overflowed export is never stranded
	// in the short-term overlay waiting for an unrelated commit or restart.
	if deltaNeedsReconcile && steps.reconcile != nil {
		if err := steps.reconcile(ctx); err != nil {
			fmt.Fprintf(out, "[watch] memory reconciliation failed (durable overlay retained): %v\n", err)
		} else {
			fmt.Fprintln(out, "[watch] long-term memory reconciliation queued")
		}
	}
	cursor := loadWatchCursor(cursorPath)
	// The hosted step pulls teammates' facts as much as it publishes local
	// ones, so it must run on idle (no-change) ticks too — a machine that only
	// receives would otherwise never sync. The defer below makes it run on
	// every exit path from here down, including a failed refresh: a failed
	// refresh never advances the main cursor, so a machine whose refresh
	// always fails (e.g. the graph plugin is missing) takes that path on every
	// tick and would otherwise be starved of the team's facts forever
	// (COR-2114; a hand-placed call per return had already missed a path
	// twice). It is token-free and throttled by its own cursor timestamp,
	// advanced regardless of outcome so a failing hosted endpoint cannot turn
	// every tick into an egress attempt. The success path still calls it
	// explicitly BEFORE the agent steps — the `ran` guard makes the deferred
	// call a no-op then — so the sync never inherits a context cancelled
	// during a long agent step and burns its throttle window on an attempt
	// that never happened.
	factsSyncRan := false
	runFactsSync := func() {
		if factsSyncRan {
			return
		}
		factsSyncRan = true
		now := steps.now().UTC()
		if steps.factsSync == nil || now.Sub(cursor.LastFactsSyncAt) < hostedSyncMinInterval {
			return
		}
		attempted, err := steps.factsSync(ctx)
		switch {
		case err != nil:
			fmt.Fprintf(out, "[watch] hosted fact sync failed (local brain unaffected): %v\n", err)
		case attempted:
			fmt.Fprintln(out, "[watch] hosted fact sync ran")
		}
		markFactsSyncAttempt(cursorPath, now)
	}
	defer runFactsSync()
	fp := steps.fingerprint(ctx)
	changed := fp != cursor.LastFingerprint || cursor.LastRefreshAt.IsZero()
	if !changed && !(cursor.PendingSeed && w.seedAgent != "none" || cursor.PendingDistill && w.distill) {
		fmt.Fprintln(out, "[watch] no change; nothing to do")
		return
	}
	// Consolidation throttle: the fingerprint includes checkpoint refs, so an
	// active agent session flips it every turn; without a throttle the heavy
	// full refresh would run every tick exactly when the machine is busiest.
	// A failed delta means nothing carried the new work, so the full refresh is
	// the repair path and must not wait the whole interval (Bugbot PR #78),
	// but it is throttled too, just on a shorter clock. The delta and the full
	// refresh contend for the SAME brain write lock, so an unthrottled repair
	// would fire the heavy path every tick for as long as the delta keeps
	// failing, contending for the very lock that broke it. watchRepairWait
	// escalates after one tick and then backs off to the normal cadence. An
	// overflowed buffer still forces consolidation immediately: recall
	// completeness is at risk, and a successful consolidation clears the
	// overlay, so it cannot repeat the way a failing delta can. The first ever
	// refresh always runs.
	if changed && w.consolidateEvery > 0 && !cursor.LastRefreshAt.IsZero() && !bufferFull {
		wait := w.consolidateEvery
		state := "short-term memory is current"
		if !deltaHealthy {
			wait = watchRepairWait(w, cursor.ConsolidationRepairs)
			state = fmt.Sprintf("short-term memory failed; repair refresh backing off after %d consecutive repairs", cursor.ConsolidationRepairs)
		}
		if since := steps.now().UTC().Sub(cursor.LastRefreshAt); since < wait {
			fmt.Fprintf(out, "[watch] consolidation deferred (%s since last full refresh; due in %s; %s)\n",
				since.Round(time.Second), (wait - since).Round(time.Second), state)
			return
		}
	}
	if changed {
		if err := steps.refresh(ctx); err != nil {
			// Refresh failed: do NOT spend tokens on an unrefreshed brain, and do NOT advance the cursor.
			// The next tick retries the free refresh before attempting pending agent work.
			fmt.Fprintf(out, "[watch] refresh failed (skipping agent work this tick): %v\n", err)
			return
		}
	}
	runFactsSync()
	reserved, reason, err := reserveWatchAgentSpend(cursorPath, fp, w, agentCalls, steps.now().UTC(), !deltaHealthy)
	if err != nil {
		fmt.Fprintf(out, "[watch] cursor update failed (skipping agent work this tick): %v\n", err)
		return
	}
	if changed {
		fmt.Fprintln(out, "[watch] refreshed (deterministic, no agent tokens)")
	}

	if !w.agentWorkEnabled() {
		return
	}
	if !reserved {
		fmt.Fprintf(out, "[watch] agent work skipped: %s\n", reason)
		return
	}
	// Gated token-spending work: agent seed synthesis and/or distill, at most once per --distill-every,
	// counted against --budget. A transient failure of one step is intentionally best-effort: we still
	// advance the spend cursor + budget below so a failed step retries on the NEXT interval, not every
	// tick (and a step that already burned tokens before failing can't be re-run for free).
	pending := loadWatchCursor(cursorPath)
	seedDone, distillDone := false, false
	seedAttempted := false
	if w.seedAgent != "none" && pending.PendingSeed {
		seedAttempted = true
		if err := steps.seed(ctx); err != nil {
			fmt.Fprintf(out, "[watch] seed synthesis failed: %v\n", err)
		} else {
			seedDone = true
			fmt.Fprintln(out, "[watch] synthesized seed (agent step; spent tokens)")
		}
	}
	if w.distill && pending.PendingDistill {
		switch err := steps.distill(ctx); {
		case errors.Is(err, errDistillPassBusy):
			// When distill was the only agent step, nothing was spent, so nothing
			// may be charged. Hand the window
			// back instead of logging "spent tokens" and going quiet until the
			// next one — otherwise a watcher installed beside `setup`'s
			// hours-long backfill loses its first window (and, if the backfill
			// outlives it, every window) to a pass that never ran.
			// A seed step attempted immediately before this may already have spent
			// tokens even when it returned an error, so its reservation must stay.
			if seedAttempted {
				fmt.Fprintln(out, "[watch] distill skipped: another pass holds this brain; the spend window remains consumed by seed synthesis")
			} else {
				releaseWatchAgentSpend(cursorPath, cursor.LastAgentSpendAt, agentCalls)
				fmt.Fprintln(out, "[watch] distill skipped: another pass holds this brain; the spend window was NOT consumed")
			}
		case errors.Is(err, errDistillDeferred):
			fmt.Fprintln(out, "[watch] distilled capped batch; remaining sessions pending for the next spend window")
		case err != nil:
			fmt.Fprintf(out, "[watch] distill failed: %v\n", err)
		default:
			distillDone = true
			fmt.Fprintln(out, "[watch] distilled facts (agent step; spent tokens)")
		}
	}
	if err := withWatchCursorLock(cursorPath, func() error {
		current := loadWatchCursor(cursorPath)
		// A newer refresh owns its own pending work.
		if current.LastFingerprint != pending.LastFingerprint || !current.LastRefreshAt.Equal(pending.LastRefreshAt) {
			return nil
		}
		if seedDone {
			current.PendingSeed = false
		}
		if distillDone {
			current.PendingDistill = false
		}
		return saveWatchCursor(cursorPath, current)
	}); err != nil {
		fmt.Fprintf(out, "[watch] completion cursor update failed: %v\n", err)
	}
}

// releaseWatchAgentSpend gives back a window reserved by reserveWatchAgentSpend
// when the gated step turned out to do nothing at all. previous is the
// LastAgentSpendAt read at the top of this tick, so the cursor lands exactly
// where it was; the budget counter is decremented for the same reason. Failures
// are deliberately silent: the worst case is the pre-existing behaviour (a
// window charged for a no-op), and a watcher must never die on cursor
// bookkeeping.
func releaseWatchAgentSpend(cursorPath string, previous time.Time, agentCalls *int) {
	_ = withWatchCursorLock(cursorPath, func() error {
		cursor := loadWatchCursor(cursorPath)
		cursor.LastAgentSpendAt = previous
		if *agentCalls > 0 {
			*agentCalls--
		}
		return saveWatchCursor(cursorPath, cursor)
	})
}

// agentWorkEnabled reports whether any token-spending step is turned on.
func (w watchCommandOptions) agentWorkEnabled() bool {
	return w.distill || w.seedAgent != "none"
}

// watchStepsForRepo builds the per-repo side effects the watch loop drives. refresh is ALWAYS the free
// (seed-agent none) deterministic refresh; seed and distill are the gated token steps. Shared by the
// single-repo `watch` and the workspace fan-out so both stay token-frugal the same way.
func watchStepsForRepo(cmd *cobra.Command, opts Options, w watchCommandOptions, repoDir string, now func() time.Time) watchSteps {
	return watchSteps{
		now:         now,
		fingerprint: func(c context.Context) string { return watchFingerprint(c, opts.Runner, repoDir) },
		delta:       func(c context.Context) (shortTermStats, error) { return watchShortTermDelta(c, cmd, opts, repoDir) },
		reconcile: func(c context.Context) error {
			_, warning, err := reconcileMemoryAndLaunch(c, opts, repoDir, "watch")
			if warning != "" {
				fmt.Fprintf(cmd.ErrOrStderr(), "warning: memory coordinator: %s\n", warning)
			}
			return err
		},
		refresh: func(c context.Context) error { return watchDeterministicRefresh(c, cmd, opts, repoDir) },
		seed:    func(c context.Context) error { return watchSeed(c, cmd, opts, w, repoDir) },
		distill: func(c context.Context) error { return watchDistill(c, cmd, opts, w, repoDir) },
		factsSync: func(c context.Context) (bool, error) {
			storage, err := repoStoragePaths(c, opts.Runner, opts.Env, repoDir)
			if err != nil {
				return false, err
			}
			branch := hostedSyncBranch(c, opts.Runner, repoDir)
			attempted, err := hostedFactsSyncAndPull(c, cmd.ErrOrStderr(), opts, repoDir, storage, branch)
			if err != nil {
				return attempted, err
			}
			if branch != distillDefaultBranch {
				also, err := hostedFactsSyncAndPull(c, cmd.ErrOrStderr(), opts, repoDir, storage, distillDefaultBranch)
				return attempted || also, err
			}
			return attempted, nil
		},
		paused: func() bool { return backgroundPaused(opts.Env) },
	}
}

// markFactsSyncAttempt persists the hosted-sync throttle timestamp. Failures
// are silent for the same reason as releaseWatchAgentSpend: a watcher must
// never die on cursor bookkeeping.
func markFactsSyncAttempt(cursorPath string, now time.Time) {
	_ = withWatchCursorLock(cursorPath, func() error {
		cursor := loadWatchCursor(cursorPath)
		cursor.LastFactsSyncAt = now
		return saveWatchCursor(cursorPath, cursor)
	})
}

// watchShortTermDelta runs the short-term memory path for one repo: quiet
// (output discarded; the tick logs one summary line), deterministic, and
// token-free. The returned stats let the tick escalate to consolidation when
// the buffer overflows.
func watchShortTermDelta(ctx context.Context, cmd *cobra.Command, opts Options, repoDir string) (shortTermStats, error) {
	perRepo := opts
	perRepo.Env.RepoRoot = repoDir
	deltaCmd := &cobra.Command{Use: "delta"}
	deltaCmd.SetOut(io.Discard)
	deltaCmd.SetErr(io.Discard)
	deltaCmd.SetContext(ctx)
	return runRefreshDeltaStats(deltaCmd, perRepo, true)
}

// watchShouldSpend decides whether the token-spending agent work (seed and/or distill) runs this tick:
// only when at least one is enabled AND --distill-every has elapsed since the last agent spend
// (cursor-tracked across restarts) AND the --budget cap is not yet reached. This is the structural
// token-frugality guarantee — it bounds seed synthesis exactly like distill.
func watchShouldSpend(w watchCommandOptions, cursor watchCursor, agentCalls int, now time.Time) (bool, string) {
	if !w.agentWorkEnabled() {
		return false, "no agent steps enabled"
	}
	if !(cursor.LastAgentSpendAt.IsZero() || now.Sub(cursor.LastAgentSpendAt) >= w.distillEvery) {
		return false, "--distill-every not elapsed"
	}
	if w.budget > 0 && agentCalls >= w.budget {
		return false, fmt.Sprintf("--budget %d reached", w.budget)
	}
	return true, ""
}

// watchRepairWait is the minimum time between full consolidations while the
// short-term delta is failing. It starts at one tick (a transient delta failure
// repairs on the very next pass) and doubles per consecutive repair up to the
// normal --consolidate-every, so a persistently failing delta degrades to the
// ordinary consolidation cadence instead of thrashing the shared brain write
// lock on every tick.
func watchRepairWait(w watchCommandOptions, repairs int) time.Duration {
	wait := w.interval
	if wait <= 0 {
		wait = time.Minute
	}
	if repairs > watchRepairBackoffMax {
		repairs = watchRepairBackoffMax
	}
	for i := 0; i < repairs && wait < w.consolidateEvery; i++ {
		wait *= 2
	}
	if wait > w.consolidateEvery {
		wait = w.consolidateEvery
	}
	return wait
}

// reserveWatchAgentSpend advances the refresh cursor after a successful full
// refresh and decides whether the gated token work may run. repair reports
// whether THIS refresh ran early because the short-term delta failed; it drives
// the watchRepairWait backoff and is cleared by the first healthy delta.
func reserveWatchAgentSpend(cursorPath, fingerprint string, w watchCommandOptions, agentCalls *int, now time.Time, repair bool) (bool, string, error) {
	var cursor watchCursor
	var reserved bool
	var reason string
	err := withWatchCursorLock(cursorPath, func() error {
		cursor = loadWatchCursor(cursorPath)
		changed := fingerprint != cursor.LastFingerprint || cursor.LastRefreshAt.IsZero()
		if changed {
			cursor.PendingSeed = cursor.PendingSeed || w.seedAgent != "none"
			cursor.PendingDistill = cursor.PendingDistill || w.distill
			cursor.LastFingerprint = fingerprint
			cursor.LastRefreshAt = now
			if repair {
				if cursor.ConsolidationRepairs < watchRepairBackoffMax {
					cursor.ConsolidationRepairs++
				}
			} else {
				cursor.ConsolidationRepairs = 0
			}
		}
		if !w.agentWorkEnabled() {
			if changed {
				return saveWatchCursor(cursorPath, cursor)
			}
			return nil
		}
		ok, skipReason := watchShouldSpend(w, cursor, *agentCalls, now)
		if !ok {
			reason = skipReason
			if changed {
				return saveWatchCursor(cursorPath, cursor)
			}
			return nil
		}
		cursor.LastAgentSpendAt = now
		*agentCalls++
		reserved = true
		return saveWatchCursor(cursorPath, cursor)
	})
	return reserved, reason, err
}

func withWatchCursorLock(cursorPath string, fn func() error) error {
	root := filepath.Dir(cursorPath)
	if info, err := os.Lstat(root); err == nil && info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("watch cursor directory must not be a symlink: %s", root)
	} else if err != nil && !os.IsNotExist(err) {
		return err
	}
	if err := rejectExistingSymlinkPathComponents(root, brainLockDirName); err != nil {
		return err
	}
	lock, err := acquireFileLock(filepath.Join(root, brainLockDirName, watchCursorLockName), "watch_locked", brainWriteLockTimeout)
	if err != nil {
		return err
	}
	defer func() { _ = lock.Close() }()
	return fn()
}

// watchFingerprint is a token-free change signal: the local checkpoint ref, the fetched (origin)
// checkpoint ref, and the worktree HEAD. Including the origin ref means a `git fetch` that brings in
// checkpoint activity from elsewhere also triggers a refresh. When all are unchanged since the cursor,
// there is nothing new to ingest.
func watchFingerprint(ctx context.Context, runner CommandRunner, repoDir string) string {
	rev := func(ref string) string {
		if runner == nil {
			return ""
		}
		out, _, err := runner.Run(ctx, repoDir, "git", "rev-parse", "--verify", "--quiet", ref)
		if err != nil {
			return ""
		}
		return strings.TrimSpace(string(out))
	}
	return rev(v1MainRef) + ":" + rev(v1OriginRef) + ":" + rev("HEAD")
}

// watchDeterministicRefresh refreshes sessions + semantic state with the seed
// agent ALWAYS "none", then durably reconciles long-term conversation work.
// The coordinator owns projection publication, retries, and crash recovery;
// watch only nudges it. Agent seed synthesis remains a separate gated step.
func watchDeterministicRefresh(ctx context.Context, cmd *cobra.Command, opts Options, repoDir string) error {
	return watchDeterministicRefreshComponents(ctx, cmd, opts, repoDir, watchTickBuildsHistoryProjection, false, nil)
}

// watchDeterministicRefreshComponents runs the free refresh with explicit failure
// policy and an optional outcome observer. Setup chooses best effort; ticks fail fast.
//
// historyIndex separates the two callers that were previously identical. A
// watch TICK passes false: it runs every few minutes, the per-tick delta
// already makes new conversations recallable, and the coordinator consolidates
// the durable projection on its own schedule. `setup` passes true, because it
// is a one-shot onboarding build (the same shape as a manual `refresh`, which
// has always defaulted history on) and it ends by telling the user to run
// `entire-brain brief`. With history unbuilt that brief silently drops its
// transcript half and prints "history index missing" instead — setup's own
// recommended next command, answering with a warning about setup's own output.
// watchDeterministicRefreshOptions is the free path's refresh configuration,
// built here rather than inline so both callers' intent — above all whether the
// history projection is built — is readable and testable in one place.
func watchDeterministicRefreshOptions(historyIndex bool) refreshCommandOptions {
	return refreshCommandOptions{
		outputDir:       defaultExportDir,
		checkpointLimit: defaultCheckpointLimit,
		entireBinary:    "entire",
		graphBinary:     "entire",
		scope:           exportScopeAll,
		// A tick must not bypass the durable work ledger: the per-tick delta
		// already makes new conversations recallable while the coordinator
		// consolidates asynchronously. A one-shot onboarding build has no next
		// tick to wait for, so `setup` asks for it explicitly.
		historyIndex: historyIndex,
		semantic:     true,
		seed: seedCommandOptions{
			includeTests:       true,
			maxFileBytes:       defaultSeedMaxFileBytes,
			maxFiles:           defaultSeedMaxFiles,
			format:             "markdown+json",
			agent:              "none", // free: deterministic seed only; agent seed is gated via watchSeed
			agentQuickTimeout:  2 * time.Minute,
			agentDeepTimeout:   10 * time.Minute,
			agentTimeoutAction: "keep-quick",
			agentMaxInputBytes: defaultAgentMaxInput,
		},
	}
}

func watchDeterministicRefreshComponents(ctx context.Context, cmd *cobra.Command, opts Options, repoDir string, historyIndex, bestEffort bool, component func(name string, err error)) error {
	perRepo := opts
	perRepo.Env.RepoRoot = repoDir
	refreshOpts := watchDeterministicRefreshOptions(historyIndex)
	refreshOpts.component = component
	refreshOpts.bestEffort = bestEffort
	sub := &cobra.Command{}
	sub.SetContext(ctx)
	sub.SetOut(cmd.OutOrStdout())
	sub.SetErr(cmd.ErrOrStderr())
	if err := runRefresh(ctx, sub, perRepo, refreshOpts); err != nil {
		return err
	}
	// Deterministic and token-free, like everything else in this step: index any
	// checkpoint commits that landed since the entity index's high-water mark.
	// Bounded and failure-silent — a missing `entire graph` provider must never
	// fail a tick that otherwise refreshed the brain. Under a reporter it is one
	// more degradable component, so `setup --json`, `status` and `doctor` can
	// name it instead of losing the reason to a discarded stderr line; with no
	// reporter the strict watch path keeps its warning and carries on exactly as
	// before.
	entityErr := refreshEntityIndexQuietly(ctx, perRepo, repoDir)
	switch {
	case component != nil:
		component(brainComponentEntities, entityErr)
	case entityErr != nil:
		fmt.Fprintf(cmd.ErrOrStderr(), "warning: entity index refresh skipped: %v\n", entityErr)
	}
	_, warning, err := reconcileMemoryAndLaunch(ctx, perRepo, repoDir, "watch")
	if warning != "" {
		fmt.Fprintf(cmd.ErrOrStderr(), "warning: memory coordinator: %s\n", warning)
	}
	if component != nil {
		component(brainComponentMemory, err)
	}
	if bestEffort {
		return nil
	}
	return err
}

// watchSeed is the GATED agent seed synthesis step: it re-synthesizes the seed on the cheap --model/
// --effort using --seed-agent, run at most once per --distill-every and counted against --budget (see
// watchShouldSpend). Reuses runSeed; --update refreshes the existing seed in place.
func watchSeed(ctx context.Context, cmd *cobra.Command, opts Options, w watchCommandOptions, repoDir string) error {
	seedOpts := seedCommandOptions{
		update:             true,
		includeTests:       true,
		maxFileBytes:       defaultSeedMaxFileBytes,
		maxFiles:           defaultSeedMaxFiles,
		format:             "markdown+json",
		agent:              w.seedAgent,
		model:              w.model,
		effort:             w.effort,
		agentQuickTimeout:  2 * time.Minute,
		agentDeepTimeout:   10 * time.Minute,
		agentTimeoutAction: "keep-quick",
		agentMaxInputBytes: defaultAgentMaxInput,
	}
	sub := &cobra.Command{}
	sub.SetContext(ctx)
	sub.SetOut(cmd.OutOrStdout())
	sub.SetErr(cmd.ErrOrStderr())
	return runSeed(ctx, sub, opts, seedOpts, repoDir)
}

// errDistillPassBusy reports that the gated distill did NOTHING because another
// process already held the brain's distill pass lock. `distill` itself treats
// that as success — someone else is doing the work — but the watcher must not:
// it had already reserved the --distill-every window, so a silent success burned
// a whole window (24h by default) on a no-op and logged "spent tokens". `setup`
// creates that collision by design, spawning an hours-long detached backfill and
// installing a watcher that ticks immediately after.
var errDistillPassBusy = errors.New("another distill pass holds this brain")

// errDistillDeferred retains pending work after a capped successful pass.
var errDistillDeferred = errors.New("distill has budget-deferred sessions")

func watchDistill(ctx context.Context, cmd *cobra.Command, opts Options, w watchCommandOptions, repoDir string) error {
	distillOpts := watchDistillOptions(w)
	busy := false
	deferred := false
	distillOpts.onDeferredSessions = func(n int) { deferred = n > 0 }
	distillOpts.onPassSkipped = func() { busy = true }
	sub := &cobra.Command{}
	sub.SetContext(ctx)
	sub.SetOut(cmd.OutOrStdout())
	sub.SetErr(cmd.ErrOrStderr())
	if err := runDistill(ctx, sub, opts, distillOpts, repoDir); err != nil {
		return err
	}
	if busy {
		return errDistillPassBusy
	}
	if deferred {
		return errDistillDeferred
	}
	return nil
}

func watchDistillOptions(w watchCommandOptions) distillCommandOptions {
	jobs := w.distillJobs
	if jobs <= 0 {
		jobs = 1
	}
	// A negative cap is a typo, not "unlimited". Only an explicit 0 means that.
	maxSessions := w.distillMaxSessions
	if maxSessions < 0 {
		maxSessions = 0
	}
	return distillCommandOptions{
		agent:               w.distillAgent,
		model:               w.model,
		effort:              w.effort,
		timeout:             defaultDistillTimeout,
		maxChunkBytes:       defaultDistillChunkSize,
		confidenceThreshold: defaultFactConfidenceThreshold,
		// The per-pass VOLUME cap. A capped pass is ordered newest-first,
		// matching what `setup` says it did and what a reader wants first; the
		// deferred remainder stays UNCACHED, so the next window picks it up
		// rather than it being skipped forever. Ordering is left alone when
		// there is no cap, so an uncapped `watch --distill` is unchanged.
		maxSessions: maxSessions,
		newestFirst: maxSessions > 0,
		jobs:        jobs,
		// concurrency is what the distill pipeline (and runDistill's guard)
		// actually reads; --jobs is only its compatibility alias. Leaving it at
		// the zero value made every gated distill the watcher ever attempted
		// fail with "--concurrency must be greater than 0" before making a
		// single agent call.
		concurrency: jobs,
	}
}

func loadWatchCursor(path string) watchCursor {
	var c watchCursor
	data, err := os.ReadFile(path)
	if err != nil {
		return c
	}
	_ = json.Unmarshal(data, &c)
	return c
}

func saveWatchCursor(path string, c watchCursor) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	data, err := json.MarshalIndent(c, "", "  ")
	if err != nil {
		return err
	}
	return writeFileAtomic(path, append(data, '\n'), 0o600)
}

