// settle writes the phase's single row.
func (o setupDaemonOutcome) settle(phase *setupui.PhaseRun) {
	switch {
	case o.err != nil:
		phase.Fail(o.summary, o.err)
	case o.skipped:
		phase.Skip(o.summary, o.details...)
	default:
		phase.OK(o.summary, o.details...)
	}
}

